commands.command:
for h in "vyos@10.100.93.10" "antrieb@10.100.93.11" "antrieb@10.100.93.12"; do
  echo "=== $h ===";
  ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o ConnectTimeout=5 "$h" "echo OK; hostname" 2>&1;
done

ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null vyos@10.100.93.10 "bash -c '
source /opt/vyatta/etc/functions/script-template;
configure;
run show interfaces;
exit;
'" 2>&1
